SELECT 


    l.store_id = #{storeId}

        AND (l.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.platform_item_id LIKE CONCAT('%', #{keyword}, '%')
             OR l.title LIKE CONCAT('%', #{keyword}, '%') OR m.code LIKE CONCAT('%', #{keyword}, '%') OR m.name LIKE CONCAT('%', #{keyword}, '%'))

    AND l.status = #{status}
    AND l.fulfillment = #{fulfillment}
    AND l.material_id IS NOT NULL
    AND l.material_id IS NULL
    AND l.material_id = #{materialId}

ORDER BY l.store_id, l.seller_sku

